CREATE COLUMN TABLE "TEST_AP"."OCRW" ("AbsEntry" INTEGER CS_INT NOT NULL , "CardCode" NVARCHAR(15) NOT NULL , "Year" SMALLINT CS_INT NOT NULL , "SentMeth" NVARCHAR(1), "SentValue" DECIMAL(21,6) CS_FIXED, "LastAMeth" NVARCHAR(1), "LastAValue" DECIMAL(21,6) CS_FIXED, "ReportID" NVARCHAR(50), PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 0  AUTO MERGE ;
CREATE UNIQUE INDEX "OCRW_BP_YEAR" ON "TEST_AP"."OCRW" ( "CardCode" ASC, "Year" ASC )